class Solution {
public:
    int minOperations(vector<int>& nums) {
        const int M = 200000;
        vector<bool> prime(M+1, true);
        prime[0] = prime[1] = false;
        for (int p = 2; p*p <= M; ++p)
            if (prime[p])
                for (int x = p*p; x <= M; x += p) prime[x] = false;
        int ans = 0;
        for (int i = 0; i < (int)nums.size(); ++i) {
            int x = nums[i];
            if ((i & 1) == 0) {
                while (!prime[x]) { ++x; ++ans; }
            } else if (prime[x]) {
                ans += (x == 2 ? 2 : 1);
            }
        }
        return ans;
    }
};
